// All records below are illustrative design data, held in memory only.
const sampleDay='2026-11-02';
const demo={targets:{calories:2700,protein:120,carbs:375,fat:80},meals:[{id:1,name:'Oats, yoghurt and banana',calories:480,protein:25,carbs:65,fat:14,date:sampleDay},{id:2,name:'Homemade zhajiang mian',calories:720,protein:30,carbs:95,fat:24,date:sampleDay}],saved:[],completed:false,sleepMinutes:440};
const session=[{name:'Barbell squat',sets:'3 × 5',note:'Quads · Glutes',cue:'Set your stance, brace your trunk and use a controlled, comfortable depth.'},{name:'Bench press',sets:'3 × 5',note:'Chest · Triceps',cue:'Keep a stable setup and lower the bar with control. Use a spotter or safety arms.'},{name:'Seated cable row',sets:'3 × 8',note:'Back · Biceps',cue:'Keep your torso steady and pull your elbows back without shrugging.'},{name:'Romanian deadlift',sets:'3 × 8',note:'Hamstrings · Glutes',cue:'Hinge at the hips, keep the load close and stop before losing your back position.'},{name:'Standing calf raise',sets:'2 × 12',note:'Calves',cue:'Rise through the forefoot with control and avoid bouncing.'},{name:'Plank',sets:'2 × 30 sec',note:'Core',cue:'Keep a comfortable neutral trunk and breathe throughout the hold.'}];
const $=s=>document.querySelector(s),num=n=>new Intl.NumberFormat('en-SG',{maximumFractionDigits:1}).format(n),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let calendarSelected=2;let selectedDate=sampleDay,editing=null,savingDish=false,selectedMuscle='biceps',side='front',partIndex=0;
function sums(day){return demo.meals.filter(m=>m.date===day).reduce((a,m)=>{for(const k of Object.keys(demo.targets))a[k]+=m[k];return a;},{calories:0,protein:0,carbs:0,fat:0});}
console.assert(demo.meals.reduce((s,m)=>s+m.calories,0)===1200,'Sample calories reconcile');
console.assert(demo.targets.protein*4+demo.targets.carbs*4+demo.targets.fat*9===demo.targets.calories,'Sample targets reconcile');
function macros(day){const total=sums(day);return Object.entries(demo.targets).map(([key,target])=>{const unit=key==='calories'?'kcal':'g',name={calories:'Calories',protein:'Protein',carbs:'Carbs',fat:'Fat'}[key];return `<div><div class="macro-line"><span>${name}</span><strong>${num(total[key])}<small> / ${num(target)} ${unit}</small></strong></div><div class="track" role="progressbar" aria-label="${name} intake" aria-valuenow="${total[key]}" aria-valuemin="0" aria-valuemax="${Math.max(target,total[key])}"><span style="width:${Math.min(100,total[key]/target*100)}%"></span></div></div>`;}).join('');}
function notice(text){$('#notice').textContent=text;setTimeout(()=>$('#notice').textContent='',3500);}
function details(title,html){$('#detailTitle').textContent=title;$('#detailContent').innerHTML=html;$('#detailDialog').showModal();}
function showExercise(e){details(e.name,`<p>${esc(e.note||e.equipment||'Movement guide')}</p>${e.steps?'<ol>'+e.steps.map(s=>'<li>'+esc(s)+'</li>').join('')+'</ol>':'<p>'+esc(e.cue)+'</p>'}<p class="muted">Design preview: the full illustrated exercise library remains available in the existing site.</p>`);}
function exerciseRows(list,compact=false){return list.map((e,i)=>`<div class="exercise-row"><div><button data-exercise="${i}"><strong>${esc(e.name)}</strong></button><small>${esc(e.note)}</small></div><span class="reps">${esc(e.sets)}</span></div>`).join('');}
$('#todayExercises').innerHTML=exerciseRows(session.slice(0,3),true);$('#fullExercises').innerHTML=exerciseRows(session);document.querySelectorAll('[data-exercise]').forEach(b=>b.onclick=()=>showExercise(session[+b.dataset.exercise]));
const week=[['Mon','2','Gym'],['Tue','3','Court'],['Wed','4','Rest'],['Thu','5','Gym'],['Fri','6','Rest'],['Sat','7','Court'],['Sun','8','Rest']];
$('#weekStrip').innerHTML=week.map(([d,n,kind])=>`<a class="day-cell ${n==='2'?'selected':''}" href="#progress" aria-label="${d} ${n} November, ${kind}"><span>${d}</span><b>${n}</b><span class="day-dot ${kind==='Rest'?'off':''}" aria-hidden="true"></span><span class="day-kind">${kind}</span></a>`).join('');
function refresh(){const total=sums(sampleDay);$('#mealCount').innerHTML=demo.meals.filter(m=>m.date===sampleDay).length+' <small>today</small>';$('#weekSessions').innerHTML=(demo.completed?1:0)+' <small>/ 2 sessions</small>';const left=demo.targets.calories-total.calories;$('#mobileFuel').textContent=`${num(Math.max(0,left))} kcal and ${num(Math.max(0,demo.targets.protein-total.protein))} g protein left today.`;$('#remaining').textContent=num(Math.max(0,left));$('.fuel-lead>span').textContent=left<0?'kcal over target':'kcal remaining';$('#todayMacros').innerHTML=macros(sampleDay);const proteinLeft=demo.targets.protein-total.protein;$('#fuelFinding').textContent=proteinLeft>0?`${num(proteinLeft)} g of protein left to your daily target.`:'Protein target reached for this sample day.';$('#nutritionMacros').innerHTML=macros(selectedDate);const meals=demo.meals.filter(m=>m.date===selectedDate);$('#journalCount').textContent=`${meals.length} ${meals.length===1?'meal':'meals'}`;$('#mealJournal').innerHTML=meals.length?meals.map(m=>`<div class="meal-row"><div><strong>${esc(m.name)}</strong><p>${num(m.protein)} g protein · ${num(m.carbs)} g carbs · ${num(m.fat)} g fat</p><button data-edit="${m.id}">Edit</button><button data-remove="${m.id}">Remove</button></div><div>${num(m.calories)} <small>kcal</small></div></div>`).join(''):'<p class="muted">No meals logged for this date. Add a meal when you’re ready.</p>';document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openMeal(demo.meals.find(m=>m.id===+b.dataset.edit)));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{demo.meals=demo.meals.filter(m=>m.id!==+b.dataset.remove);refresh();notice('Meal removed from the preview.');});$('#savedDishes').innerHTML=demo.saved.length?demo.saved.map((m,i)=>`<div class="saved-dish-row"><div><strong>${esc(m.name)}</strong><p>${num(m.calories)} kcal · ${num(m.protein)} g protein</p></div><div><button data-reuse="${i}">Use dish</button><button data-forget="${i}" aria-label="Remove saved ${esc(m.name)}">Remove</button></div></div>`).join(''):'<p class="panel-note">No saved dishes. Save one of your own to see it here.</p>';document.querySelectorAll('[data-reuse]').forEach(b=>b.onclick=()=>openMeal({...demo.saved[+b.dataset.reuse],id:null,date:selectedDate}));document.querySelectorAll('[data-forget]').forEach(b=>b.onclick=()=>{demo.saved.splice(+b.dataset.forget,1);refresh();});}
function openMeal(meal=null,saveDish=false){editing=meal?.id||null;savingDish=saveDish;const f=$('#mealForm');f.reset();$('#mealTitle').textContent=saveDish?'Save a dish':editing?'Edit meal':'Log a meal';f.elements.date.value=meal?.date||selectedDate;for(const key of ['name','calories','protein','carbs','fat'])if(meal)f.elements[key].value=meal[key];$('#mealDialog').showModal();}
document.querySelectorAll('[data-log]').forEach(b=>b.onclick=()=>{selectedDate=location.hash==='#nutrition'?$('#nutritionDate').value:sampleDay;openMeal();});$('#saveDishButton').onclick=()=>openMeal(null,true);
$('#mealForm').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;const meal={id:editing||Date.now(),name:f.elements.name.value.trim(),date:f.elements.date.value};for(const k of Object.keys(demo.targets))meal[k]=Number(f.elements[k].value);if(!meal.name)return;if(savingDish)demo.saved.push({...meal,id:null});else if(editing)demo.meals=demo.meals.map(m=>m.id===editing?meal:m);else demo.meals.push(meal);$('#mealDialog').close();refresh();notice(savingDish?'Dish saved in this preview.':'Meal saved in this preview.');};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('#startWorkout').onclick=()=>{location.hash='#training';details('Full body A',`<p>Sample session · 55 minutes</p><p>Complete your planned working sets, then mark the session below.</p><button class="primary" id="finishSession">${demo.completed?'Mark incomplete':'Mark session complete'}</button>`);$('#finishSession').onclick=()=>{demo.completed=!demo.completed;$('#sessionStatus').textContent=demo.completed?'Session completed in the preview.':'Warm up, then begin your working sets.';$('#startWorkout').textContent=demo.completed?'Review session →':'Start session →';refresh();$('#detailDialog').close();notice('Sample session updated.');};};
document.querySelectorAll('[data-sleep]').forEach(b=>b.onclick=()=>{details('Log sleep','<form id="sleepForm"><div class="form-grid"><label>Hours<input name="hours" type="number" min="0" max="24" value="'+Math.floor(demo.sleepMinutes/60)+'" required></label><label>Minutes<input name="minutes" type="number" min="0" max="59" value="'+demo.sleepMinutes%60+'" required></label></div><button class="primary" type="submit">Save to preview</button></form>');$('#sleepForm').onsubmit=e=>{e.preventDefault();const f=e.currentTarget;demo.sleepMinutes=Number(f.elements.hours.value)*60+Number(f.elements.minutes.value);if(demo.sleepMinutes>1440){f.elements.hours.setCustomValidity('Enter no more than 24 hours.');f.reportValidity();return;}const t=`${Math.floor(demo.sleepMinutes/60)} h ${demo.sleepMinutes%60} m`;$('#sleepReadout').innerHTML=t+' <small>/ 8 h</small>';$('#sleepFill').style.width=Math.min(100,demo.sleepMinutes/480*100)+'%';document.querySelector('.summary-strip>div:last-child strong').textContent=t;$('#detailDialog').close();};});
function setDate(value){selectedDate=value;$('#nutritionDate').value=value;$('#nutritionDateLabel').textContent=new Date(value+'T12:00:00').toLocaleDateString('en-SG',{weekday:'long',day:'numeric',month:'long'})+' · Sample journal';refresh();}
$('#nutritionDate').onchange=e=>{if(e.target.value)setDate(e.target.value);};for(const [id,delta] of [['previousDay',-1],['nextDay',1]])$('#'+id).onclick=()=>{const d=new Date(selectedDate+'T12:00:00');d.setDate(d.getDate()+delta);setDate(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`);};$('#todayButton').onclick=()=>setDate(sampleDay);
$('#targetsButton').onclick=()=>details('Sample targets',`<p>2,700 kcal · 120 g protein · 375 g carbs · 80 g fat</p><p>This preview demonstrates the layout. Your existing profile calculator would supply the real targets when the design is integrated.</p>`);
$('#routineButton').onclick=()=>details('Routine preferences','<p>Sample schedule: two gym sessions and two badminton sessions each week.</p><p>The full routine builder and saved training plan will be connected after the design is approved.</p>');
$('#account').onclick=()=>details('Sample profile','<p>Design demonstration · no Google sign-in or cloud access.</p><p>The final account view would contain your profile, date of birth, weight, goals and save status.</p>');
function showMuscle(){const m=MUSCLES[selectedMuscle],p=m.parts[partIndex];$('#conceptBody').innerHTML=AnatomyMap.create(selectedMuscle,side,'concept');$('#muscleChoice').value=selectedMuscle;$('#muscleName').textContent=m.name;$('#muscleParts').innerHTML=m.parts.map((p,i)=>`<button role="tab" aria-selected="${i===partIndex}" data-part="${i}">${esc(p.name)}</button>`).join('');$('#muscleDescription').textContent=p.description;$('#growthDescription').textContent=m.growth;$('#muscleExercises').innerHTML=p.moves.filter(id=>EXERCISES[id]).map(id=>`<div class="exercise-row"><button data-move="${id}"><strong>${esc(EXERCISES[id].name)}</strong><small>${esc(EXERCISES[id].equipment)}</small></button><span aria-hidden="true">↗</span></div>`).join('');document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{partIndex=+b.dataset.part;showMuscle();});document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>showExercise(EXERCISES[b.dataset.move]));$('#conceptBody').querySelectorAll('[data-muscle]').forEach(g=>{const choose=()=>{selectedMuscle=g.dataset.muscle;partIndex=0;showMuscle();};g.addEventListener('click',choose);g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}});});}
$('#muscleChoice').innerHTML=Object.entries(MUSCLES).map(([k,m])=>`<option value="${k}">${esc(m.name)}</option>`).join('');$('#muscleChoice').onchange=e=>{selectedMuscle=e.target.value;partIndex=0;showMuscle();};document.querySelectorAll('[data-side]').forEach(b=>b.onclick=()=>{side=b.dataset.side;document.querySelectorAll('[data-side]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));showMuscle();});document.querySelectorAll('[data-training]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-training]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));$('#routineView').hidden=b.dataset.training!=='routine';$('#muscleView').hidden=b.dataset.training!=='muscles';});
$('#calendarGrid').innerHTML=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(s=>`<span>${s}</span>`).join('')+Array.from({length:6},()=>'<span class="spacer"></span>').join('')+Array.from({length:30},(_,i)=>`<button data-calendar="${i+1}" aria-pressed="${i===1}">${i+1}${[2,3,5,7].includes(i+1)?'<span class="day-dot" aria-hidden="true"></span>':''}</button>`).join('');
function dayDetail(n){calendarSelected=n;const date=`2026-11-${String(n).padStart(2,'0')}`,total=sums(date),has=demo.meals.some(m=>m.date===date);document.querySelectorAll('[data-calendar]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.calendar===n)));$('#dayDetail').innerHTML=`<h2>${new Date(date+'T12:00:00').toLocaleDateString('en-SG',{weekday:'long',day:'numeric',month:'long'})}</h2><p class="day-description">${n===2?'Full body A · '+(demo.completed?'Completed':'Planned'):n===5?'Full body B · Planned':[3,7].includes(n)?'Badminton · Planned':'Rest / no workout scheduled'}</p><dl class="day-metrics"><div><dt>Calories logged</dt><dd>${num(total.calories)} <small>kcal</small></dd></div><div><dt>Protein logged</dt><dd>${num(total.protein)} <small>g</small></dd></div><div><dt>Carbs logged</dt><dd>${num(total.carbs)} <small>g</small></dd></div><div><dt>Fat logged</dt><dd>${num(total.fat)} <small>g</small></dd></div></dl><p class="panel-note">${has?'Daily calorie target not reached in this sample.':'No meals logged for this date.'}</p><button class="secondary" id="editCalendarMeals">Review / edit meals →</button>`;$('#editCalendarMeals').onclick=()=>{setDate(date);location.hash='#nutrition';};}
document.querySelectorAll('[data-calendar]').forEach(b=>b.onclick=()=>dayDetail(+b.dataset.calendar));
function route(){const id=['today','training','nutrition','progress'].includes(location.hash.slice(1))?location.hash.slice(1):'today';document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==id);document.querySelectorAll('.app-header nav a').forEach(a=>{if(a.hash==='#'+id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(id==='progress')dayDetail(calendarSelected);window.scrollTo(0,0);}
addEventListener('hashchange',route);refresh();showMuscle();dayDetail(2);route();

$('.learning-link a').addEventListener('click',()=>document.querySelector('[data-training=muscles]').click());
$('#weekStrip').querySelectorAll('a').forEach((a,i)=>a.addEventListener('click',()=>{calendarSelected=i+2;if(location.hash==='#progress')dayDetail(calendarSelected);}));
